SUBJ = list(BANK)
def build(start):
    # interleave subjects so consecutive days differ; slot A uses topic i of subject s, slot B uses a different subject
    seqA = [(s, BANK[s][i]) for i in range(20) for s in SUBJ]
    seqB = seqA[199:] + seqA[:199]   # B starts half a cycle later, so a topic's two angles are ~6 months apart
    rows = []
    for d in range(365):
        day = start + dt.timedelta(days=d)
        for slot, seq, angle in (("A", seqA, "Myth or fact / warning sign"), ("B", seqB, "How your body works")):
            s, t = seq[d % len(seq)]
            rows.append([d + 1, day.isoformat(), slot, s, t, angle])
    return rows
if __name__ == "__main__":
    start = dt.date.fromisoformat(sys.argv[1]) if len(sys.argv) > 1 else dt.date.today()
    with open("calendar.csv", "w", newline="") as f:
        w = csv.writer(f); w.writerow(["day", "date", "slot", "subject", "topic", "angle"]); w.writerows(build(start))
    print("calendar.csv", 365 * 2, "rows from", start)
